for t in cyclictest stress-ng stress taskset chrt timeout sha256sum ip ping gcc python3 base64 tar wget nc; do command -v "$t" || echo "missing:$t"; done; ls -l /sys/class/leds /sys/class/rtc /sys/class/pwm /sys/class/thermal /dev/input /dev/i2c-* /dev/gpiochip* /dev/ttyPS* /dev/ttyUL* 2>/dev/null; cat /proc/bus/input/devices; ip addr; cat /proc/partitions; ls /sys/bus/usb/devices; for p in /sys/class/thermal/thermal_zone*; do [ -d "$p" ] || continue; echo "$p"; cat "$p/type" "$p/temp" "$p"/trip_point* 2>/dev/null; done; zcat /proc/config.gz | grep -E 'CONFIG_(INPUT_KEYBOARD|KEYBOARD_GPIO|SPI_SPIDEV|PWM|FTRACE|HIGH_RES_TIMERS|I2C_XILINX|EEPROM_AT24)'; for p in /sys/firmware/devicetree/base/amba/spi@ff040000/status /sys/firmware/devicetree/base/amba/spi@ff050000/status /sys/firmware/devicetree/base/keys/compatible; do echo "$p"; [ ! -f "$p" ] || tr '\000' '\n' < "$p"; done; ls -l /sys/bus/i2c/devices/*-0050/driver /sys/bus/i2c/devices/*-0050/eeprom; ls /media
